const { invoice } = require('../invoice');
const { toCents } = require('../parse');
const { formatCents } = require('../format');
const { discountCents } = require('../discount');

test('totals a simple order', () => {
  assert.deepStrictEqual(invoice([{ name: 'Mug', price: '19.99', qty: 1 }]), ['Mug: 19.99', 'Total: 19.99']);
});

test('prices convert to cents without losing a cent', () => {
  assert.strictEqual(toCents('19.99'), 1999);
  assert.strictEqual(toCents('0.29'), 29);
  assert.strictEqual(toCents('-0.50'), -50);
});

test('formats negative amounts with a single leading minus', () => {
  assert.strictEqual(formatCents(-50), '-0.50');
  assert.strictEqual(formatCents(-1234), '-12.34');
  assert.strictEqual(formatCents(1234), '12.34');
});

test('discount rounds to the nearest cent', () => {
  assert.strictEqual(discountCents(1005, 10), 101);
  assert.strictEqual(discountCents(-1005, 10), -101);
});

test('refund line prints correctly', () => {
  assert.deepStrictEqual(invoice([{ name: 'Refund', price: '-0.50', qty: 1 }]), ['Refund: -0.50', 'Total: -0.50']);
});

test('order with percent discount has correct cents', () => {
  assert.deepStrictEqual(
    invoice([{ name: 'A', price: '19.99', qty: 1 }, { name: 'B', price: '0.29', qty: 1 }], 10),
    ['A: 19.99', 'B: 0.29', 'Discount: -2.03', 'Total: 18.25'],
  );
});

